func:
msg.topic = "CREATE TABLE IF NOT EXISTS _claude_sqlite_test (" +
    "id INTEGER PRIMARY KEY AUTOINCREMENT, job_name TEXT NOT NULL, checked_at TEXT NOT NULL)";
return msg;

node.warn('CREATE result: ' + JSON.stringify(msg.payload));
msg.topic = "INSERT INTO _claude_sqlite_test (job_name, checked_at) VALUES ('sqlite_test_probe', datetime('now'))";
return msg;

node.warn('INSERT result: ' + JSON.stringify(msg.payload));
msg.topic = 'SELECT * FROM _claude_sqlite_test ORDER BY id DESC LIMIT 5';
return msg;

const problems = [];
const rows = msg.payload;
node.warn('SELECT result: ' + JSON.stringify(rows));
if (!Array.isArray(rows)) {
    problems.push('Expected msg.payload to be an array of row objects for a SELECT — got ' + typeof rows + '. This is exactly the assumption this test exists to check; if wrong, tell me the real shape from the RESULT debug output and the query/result handling in the real flows gets built against that instead.');
} else if (rows.length === 0) {
    problems.push('SELECT returned zero rows right after an INSERT into the same table — either the INSERT silently failed, or results need to be read a different way than msg.payload.');
} else {
    const first = rows[0];
    if (!('job_name' in first) || !('checked_at' in first)) {
        problems.push('Row object does not have the expected column keys — got keys: ' + Object.keys(first).join(', '));
    }
}
msg.test_problems = problems;
msg.topic = 'DROP TABLE IF EXISTS _claude_sqlite_test';
return msg;

node.warn('DROP TABLE (cleanup) result: ' + JSON.stringify(msg.payload));
const problems = msg.test_problems || [];
msg.payload = {
    part: 'A - scratch DB round-trip (CREATE/INSERT/SELECT/DROP)',
    result: problems.length ? 'PROBLEMS FOUND' : 'ALL CHECKS PASSED — node type + query/result shape confirmed',
    problems: problems,
};
return [msg, problems.length ? msg : null];

node.warn('Real-DB table list: ' + JSON.stringify(msg.payload));
msg.payload = {
    part: 'B - real SQLite Web database, read-only reachability check',
    result: 'Reached the file and ran a query — see existing_tables for what is actually in there.',
    existing_tables: msg.payload,
    note: 'If this errored instead of returning, the CFG_REAL config node\'s db path is still the CHANGE_ME placeholder, or is pointed at the wrong file — fix that field and retry before trusting anything else here.',
};
return msg;

const out = (msg.payload || '').toString().trim();
const found = out && !out.includes('NOT_FOUND');
node.warn('sqlite3 CLI check raw output: ' + JSON.stringify(out));
msg.payload = {
    part: 'C - sqlite3 CLI availability in the Node-RED container',
    result: found ? 'FOUND — exec+CLI is a viable path, no npm palette needed' : 'NOT FOUND — either install a SQLite palette (watch for a native-build failure on Alpine) or add sqlite3 to the container another way',
    raw_output: out,
};
return msg;
